    ItemCard(english: "She can't be pregnant because she reached her menopause two years ago.", translations: {"ar": "هي مش ممكن تكون حامل عشان هي وصلت لسن اليأس من سنتين", "de": "Sie kann nicht schwanger sein, weil sie vor zwei Jahren in die Wechseljahre gekommen ist", "es": "No puede estar embarazada porque llegó a la menopausia hace dos años", "fr": "Elle ne peut pas être enceinte car elle a atteint la ménopause il y a deux ans", "it": "Non può essere incinta perché è arrivata alla menopausa due anni fa", "ru": "Она не может быть беременна, потому что у нее наступила менопауза два года назад", "zh": "她不可能怀孕，因为她两年前就到了更年期", "tr": "Hamile olamaz çünkü iki yıl önce menopoza girdi", "en": "She can't be pregnant because she reached her menopause two years ago."}),
    ItemCard(english: "My brothers' fiancée is so cute, and I think they're the best couple.", translations: {"ar": "خطيبة أخويا جميلة أوي وأظن إنهم أفضل زوج/ اتنين مرتبطين", "de": "Die Verlobte meines Bruders ist so süß, und ich denke, sie sind das beste Paar", "es": "La prometida de mi hermano es tan linda, y creo que son la mejor pareja", "fr": "La fiancée de mon frère est si mignonne, et je pense qu'ils sont le meilleur couple", "it": "La fidanzata di mio fratello è così carina, e penso che siano la migliore coppia", "ru": "Невеста моего брата такая милая, и я думаю, они лучшая пара", "zh": "我哥哥的未婚妻太可爱了，我认为他们是最好的情侣", "tr": "Erkek kardeşimin nişanlısı çok tatlı ve bence onlar en iyi çift", "en": "My brothers' fiancée is so cute, and I think they're the best couple."}),
    ItemCard(english: "Ali didn't love any woman after his wife's death, he is a sincere widower.", translations: {"ar": "علي ماحبش أي ست من بعد موت زوجته. هو أرمل مخلص", "de": "Ali liebte nach dem Tod seiner Frau keine andere Frau, er ist ein aufrichtiger Witwer", "es": "Ali no amó a ninguna mujer después de la muerte de su esposa, es un viudo sincero", "fr": "Ali n'a aimé aucune femme après la mort de sa femme, c'est un veuf sincère", "it": "Ali non amò nessuna donna dopo la morte di sua moglie, è un vedovo sincero", "ru": "Али не любил ни одной женщины после смерти жены, он искренний вдовец", "zh": "阿里在妻子去世后没有再爱过任何女人，他是一个真诚的鳏夫", "tr": "Ali karısının ölümünden sonra hiçbir kadını sevmedi, samimi bir dul erkek", "en": "Ali didn't love any woman after his wife's death, he is a sincere widower."}),
    ItemCard(english: "Do you know that King Lear had three daughters and no sons?", translations: {"ar": "انت عارف ان الملك لير كان عنده 3 بنات ومعندوش ولا ابن؟", "de": "Weißt du, dass König Lear drei Töchter und keine Söhne hatte?", "es": "¿Sabes que el Rey Lear tenía tres hijas y ningún hijo?", "fr": "Savez-vous que le roi Lear avait trois filles et aucun fils?", "it": "Sai che Re Lear aveva tre figlie e nessun figlio maschio?", "ru": "Знаете ли вы, что у короля Лира было три дочери и ни одного сына?", "zh": "你知道李尔王有三个女儿而没有儿子吗？", "tr": "Kral Lear'ın üç kızı olduğunu ve hiç oğlu olmadığını biliyor musun?", "en": "Do you know that King Lear had three daughters and no sons?"}),
    ItemCard(english: "His mother-in-law has been ill since his father-in-law died.", translations: {"ar": "حماته تعبانه من وقت ما حماه اتوفى", "de": "Seiner Schwiegermutter geht es schlecht, seit sein Schwiegervater gestorben ist", "es": "Su suegra ha estado enferma desde que murió su suegro", "fr": "Sa belle-mère est malade depuis que son beau-père est mort", "it": "Sua suocera è malata da quando è morto suo suocero", "ru": "Его теща болеет с тех пор, как умер его тесть", "zh": "自从他的岳父去世后，他的岳母就一直生病", "tr": "Kayınpederi öldüğünden beri kayınvalidesi hasta", "en": "His mother-in-law has been ill since his father-in-law died."}),
    ItemCard(english: "Don't listen to him; he is a senile man.", translations: {"ar": "ما تسمعش كلامه ده راجل كبر وخرف", "de": "Hör nicht auf ihn; er ist ein seniler Mann", "es": "No lo escuches; es un hombre senil", "fr": "Ne l'écoute pas; c'est un homme sénile", "it": "Non ascoltarlo; è un uomo senile", "ru": "Не слушай его; он старый и слабоумный", "zh": "别听他的；他是个老糊涂的人", "tr": "Onu dinleme; o bunak bir adam", "en": "Don't listen to him; he is a senile man."}),
    ItemCard(english: "Her parents were divorced long time ago, so she lives with her mother and her step-dad.", translations: {"ar": "باباها ومامتها انفصلوا من وقت طويل عشان كده هي عايشة مع مامتها وجوز مامتها", "de": "Ihre Eltern wurden vor langer Zeit geschieden, also lebt sie mit ihrer Mutter und ihrem Stiefvater", "es": "Sus padres se divorciaron hace mucho tiempo, así que vive con su madre y su padrastro", "fr": "Ses parents ont divorcé il y a longtemps, alors elle vit avec sa mère et son beau-père", "it": "I suoi genitori hanno divorziato molto tempo fa, quindi vive con sua madre e il suo patrigno", "ru": "Ее родители развелись давно, поэтому она живет с матерью и отчимом", "zh": "她的父母很久以前就离婚了，所以她和她的母亲和继父住在一起", "tr": "Anne babası uzun zaman önce boşandı, bu yüzden annesi ve üvey babasıyla yaşıyor", "en": "Her parents were divorced long time ago, so she lives with her mother and her step-dad."}),
    ItemCard(english: "I love my family very much.", translations: {"ar": "أنا بحب عيلتي أوي", "de": "Ich liebe meine Familie sehr", "es": "Quiero mucho a mi familia", "fr": "J'aime beaucoup ma famille", "it": "Amo molto la mia famiglia", "ru": "Я очень люблю свою семью", "zh": "我非常爱我的家人", "tr": "Ailemi çok seviyorum", "en": "I love my family very much."}),
    ItemCard(english: "My father is a doctor.", translations: {"ar": "والدي دكتور", "de": "Mein Vater ist Arzt", "es": "Mi padre es médico", "fr": "Mon père est médecin", "it": "Mio padre è un medico", "ru": "Мой отец врач", "zh": "我的父亲是一名医生", "tr": "Babam doktordur", "en": "My father is a doctor."}),
    ItemCard(english: "My mother is a teacher.", translations: {"ar": "أمي معلمة", "de": "Meine Mutter ist Lehrerin", "es": "Mi madre es maestra", "fr": "Ma mère est enseignante", "it": "Mia madre è un'insegnante", "ru": "Моя мама учительница", "zh": "我的母亲是一名教师", "tr": "Annem öğretmendir", "en": "My mother is a teacher."}),
    ItemCard(english: "I have one brother and two sisters.", translations: {"ar": "عندي أخ واحد وأختين", "de": "Ich habe einen Bruder und zwei Schwestern", "es": "Tengo un hermano y dos hermanas", "fr": "J'ai un frère et deux sœurs", "it": "Ho un fratello e due sorelle", "ru": "У меня есть один брат и две сестры", "zh": "我有一个兄弟和两个姐妹", "tr": "Bir erkek kardeşim ve iki kız kardeşim var", "en": "I have one brother and two sisters."}),
    ItemCard(english: "My grandfather tells me stories about the past.", translations: {"ar": "جدي بيحكيلي قصص عن الماضي", "de": "Mein Großvater erzählt mir Geschichten über die Vergangenheit", "es": "Mi abuelo me cuenta historias sobre el pasado", "fr": "Mon grand-père me raconte des histoires sur le passé", "it": "Mio nonno mi racconta storie del passato", "ru": "Мой дедушка рассказывает мне истории о прошлом", "zh": "我的祖父给我讲关于过去的故事", "tr": "Dedem bana geçmişle ilgili hikayeler anlatır", "en": "My grandfather tells me stories about the past."}),
    ItemCard(english: "My grandmother makes the best cookies.", translations: {"ar": "جدتي بتعمل أحلى بسكويت", "de": "Meine Großmutter macht die besten Kekse", "es": "Mi abuela hace las mejores galletas", "fr": "Ma grand-mère fait les meilleurs biscuits", "it": "Mia nonna fa i biscotti migliori", "ru": "Моя бабушка печет лучшее печенье", "zh": "我的祖母做最好吃的饼干", "tr": "Büyükannem en iyi kurabiyeleri yapar", "en": "My grandmother makes the best cookies."}),
    ItemCard(english: "My uncle lives in America.", translations: {"ar": "عمي عايش في أمريكا", "de": "Mein Onkel lebt in Amerika", "es": "Mi tío vive en Estados Unidos", "fr": "Mon oncle vit en Amérique", "it": "Mio zio vive in America", "ru": "Мой дядя живет в Америке", "zh": "我的叔叔住在美国", "tr": "Amcam Amerika'da yaşıyor", "en": "My uncle lives in America."}),
    ItemCard(english: "I am the youngest child in my family.", translations: {"ar": "أنا أصغر واحد في عيلتي", "de": "Ich bin das jüngste Kind in meiner Familie", "es": "Soy el hijo menor de mi familia", "fr": "Je suis le plus jeune enfant de ma famille", "it": "Sono il figlio più piccolo della mia famiglia", "ru": "Я самый младший ребенок в семье", "zh": "我是家里最小的孩子", "tr": "Ailemin en küçük çocuğuyum", "en": "I am the youngest child in my family."}),
    ItemCard(english: "My sister is getting married next month.", translations: {"ar": "أختي هتتجوز الشهر الجاي", "de": "Meine Schwester heiratet nächsten Monat", "es": "Mi hermana se casa el próximo mes", "fr": "Ma sœur se marie le mois prochain", "it": "Mia sorella si sposa il mese prossimo", "ru": "Моя сестра выходит замуж в следующем месяце", "zh": "我妹妹下个月要结婚了", "tr": "Kız kardeşim gelecek ay evleniyor", "en": "My sister is getting married next month."}),
    ItemCard(english: "We are a family of five.", translations: {"ar": "إحنا عيلة من خمسة أفراد", "de": "Wir sind eine fünfköpfige Familie", "es": "Somos una familia de cinco", "fr": "Nous sommes une famille de cinq", "it": "Siamo una famiglia di cinque persone", "ru": "Нас в семье пятеро", "zh": "我们是一家五口", "tr": "Beş kişilik bir aileyiz", "en": "We are a family of five."}),
  ];

  @override
  Widget build(BuildContext context) {
    return ProfessionsTabScreen(
      learningLanguage: learningLanguage,
      words: words,
      sentences: sentences,
      title: "العائلة - Family",
    );
  }
