    ItemCard(english: "He doesn't believe in polygamy.", translations: {"ar": "هو مش مؤمن بتعدد الزوجات", "de": "Er glaubt nicht an Polygamie", "es": "No cree en la poligamia", "fr": "Il ne croit pas à la polygamie", "it": "Non crede nella poligamia", "ru": "Он не верит в полигамию", "zh": "他不相信一夫多妻制", "tr": "Poliandriye inanmıyor"}),
    ItemCard(english: "The bride's father walked her down the aisle.", translations: {"ar": "أبو العروسة مشى بيها في الصالة", "de": "Der Vater der Braut führte sie zum Altar", "es": "El padre de la novia la acompañó por el pasillo", "fr": "Le père de la mariée l'a accompagnée dans l'allée", "it": "Il padre della sposa l'ha accompagnata all'altare", "ru": "Отец невесты провел ее к алтарю", "zh": "新娘的父亲陪她走过红毯", "tr": "Gelinin babası onu koridorda yürüttü"}),
    ItemCard(english: "They are living a happy married life.", translations: {"ar": "هما عايشين حياة جواز سعيدة", "de": "Sie führen ein glückliches Eheleben", "es": "Ellos viven una vida matrimonial feliz", "fr": "Ils vivent une vie conjugale heureuse", "it": "Vivono una vita matrimoniale felice", "ru": "Они живут счастливой семейной жизнью", "zh": "他们过着幸福的婚姻生活", "tr": "Mutlu bir evlilik hayatı yaşıyorlar"}),
