    ItemCard(english: "The marriage was arranged by their families.", translations: {"ar": "الجواز كان مرتب من العيلتين", "de": "Die Ehe wurde von ihren Familien arrangiert", "es": "El matrimonio fue arreglado por sus familias", "fr": "Le mariage a été arrangé par leurs familles", "it": "Il matrimonio è stato combinato dalle loro famiglie", "ru": "Брак был устроен их семьями", "zh": "这桩婚姻是由他们的家庭安排的", "tr": "Evlilik aileleri tarafından ayarlandı"}),
    ItemCard(english: "He bought her a gold ring as a gift.", translations: {"ar": "هو اشترى لها خاتم دهب كهدية", "de": "Er kaufte ihr einen goldenen Ring als Geschenk", "es": "Le compró un anillo de oro como regalo", "fr": "Il lui a acheté une bague en or comme cadeau", "it": "Le ha comprato un anello d'oro come regalo", "ru": "Он купил ей золотое кольцо в подарок", "zh": "他给她买了一个金戒指作为礼物", "tr": "Ona hediye olarak altın bir yüzük aldı"}),
    ItemCard(english: "She is looking for a marriage partner online.", translations: {"ar": "هي بدور على شريك جواز على النت", "de": "Sie sucht online nach einem Ehepartner", "es": "Ella está buscando pareja para matrimonio en línea", "fr": "Elle cherche un partenaire de mariage en ligne", "it": "Sta cercando un partner per il matrimonio online", "ru": "Она ищет партнера для брака в интернете", "zh": "她正在网上寻找结婚对象", "tr": "İnternette evlilik partneri arıyor"}),
    ItemCard(english: "They are still separated but not divorced.", translations: {"ar": "هما لسة منفصلين بس مش مطلقين", "de": "Sie sind noch getrennt, aber nicht geschieden", "es": "Todavía están separados pero no divorciados", "fr": "Ils sont toujours séparés mais pas divorcés", "it": "Sono ancora separati ma non divorziati", "ru": "Они все еще раздельно, но не разведены", "zh": "他们仍然分居但没有离婚", "tr": "Hala ayrılar ama boşanmamışlar"}),
    ItemCard(english: "The wedding ceremony was beautiful and emotional.", translations: {"ar": "حفل الجواز كان جميل ومؤثر", "de": "Die Hochzeitszeremonie war schön und emotional", "es": "La ceremonia de la boda fue hermosa y emotiva", "fr": "La cérémonie de mariage était belle et émouvante", "it": "La cerimonia nuziale è stata bella ed emozionante", "ru": "Свадебная церемония была красивой и трогательной", "zh": "婚礼仪式美丽而感人", "tr": "Düğün töreni güzel ve duygusaldı"}),
    ItemCard(english: "He has been single for five years.", translations: {"ar": "هو أعزب من خمس سنين", "de": "Er ist seit fünf Jahren ledig", "es": "Ha sido soltero durante cinco años", "fr": "Il est célibataire depuis cinq ans", "it": "È single da cinque anni", "ru": "Он холост уже пять лет", "zh": "他已经单身五年了", "tr": "Beş yıldır bekar"}),
    ItemCard(english: "The couple is expecting their first child.", translations: {"ar": "العرسان مستنيين أول طفل ليهم", "de": "Das Paar erwartet sein erstes Kind", "es": "La pareja espera su primer hijo", "fr": "Le couple attend son premier enfant", "it": "La coppia aspetta il suo primo figlio", "ru": "Пара ожидает первого ребенка", "zh": "这对夫妇期待着他们的第一个孩子", "tr": "Çift ilk çocuklarını bekliyor"}),
    ItemCard(english: "She wants to keep her maiden name after marriage.", translations: {"ar": "هي عايزة تخلّي اسم عيلتها بعد الجواز", "de": "Sie möchte ihren Mädchennamen nach der Heirat behalten", "es": "Quiere conservar su apellido de soltera después del matrimonio", "fr": "Elle veut garder son nom de jeune fille après le mariage", "it": "Vuole mantenere il suo cognome da nubile dopo il matrimonio", "ru": "Она хочет оставить свою девичью фамилию после замужества", "zh": "她想婚后保留自己的娘家姓", "tr": "Evlilikten sonra kızlık soyadını korumak istiyor"}),
  ];

